import {readFile,writeFile} from 'node:fs/promises';
const date='2026-11-01',base=`data/dev/source-archives/audit-0900-${date}/`;
const read=async n=>JSON.parse(await readFile(base+n,'utf8'));
const results=(await Promise.all(['initial-results.json','extra-results.json','primary-results.json','rwe-results.json'].map(read))).flat();
const source=url=>results.find(r=>r.url===url);
const findings=[
 {key:'rwe-bench',importance:'high',sourceDate:'2026-10-28',dateSemantics:'Official /js/rwe-data.js resultsDate=2026-10-28. Export 2026-10-25 is not publication date. Chinese article published 2026-11-01 and says launch Oct27; preserve separate semantics.',urls:['https://xplore.ai/rwe-bench','https://xplore.ai/js/rwe-data.js','https://aiera.com.cn/asi-post.html?id=121637'],facts:'20 tasks: mechanical9/aerospace6/electrical5; up to24h,5 attempts. Mean per-run success: Astra37%,Opus5.5 29%,Sol25%. Pass@5 differs:60%,70%,50%. 95% credible intervals overlap; provisional=true. Native harness reasoning labels differ (Gemini high; Qwen/Grok xhigh), despite generic prose claiming max.',limits:'Do not imply best overall engineering ability or statistical separation. Cost is per run, not per successful task. Deterministic solver checks, not LLM judge. Benchmark operator also sells training environments; tasks not licensed for training.'},
 {key:'clasharness',importance:'high',sourceDate:'2026-10-13',dateSemantics:'arXiv submission Tue13Oct2026 20:01:18UTC (Shanghai Oct14); original paper submission date retained, Nov1 is Chinese media report date.',urls:['https://github.com/google-research/CLASHarness','https://arxiv.org/abs/2610.19128','https://aiera.com.cn/asi-post.html?id=121624'],facts:'Read official README, paper metadata and Chinese publisher full text;600 conflict episodes,20domains,23plugins,15models. Code Apache2.0,dataset CC-BY4.0. Connector confirms exact Google-research repo,not a fork,9stars,pushedOct15.',limits:'Official repository explicitly says not officially supported Google product; cannot describe as newly released Nov1 merely because Chinese report is new. Read declared known unfair-check issues, mixed semantic/deterministic grading.'},
 {key:'treg',importance:'high',sourceDate:'2026-11-01',dateSemantics:'Date of QbitAI media report; official announcement timestamp not independently retrieved (X and oEmbed fetch failed).',urls:['https://www.qbitai.com/2026/11/506922.html','https://github.com/superdesigndev/treg'],facts:'Read full QbitAI article and official README. Report describes Jev judgment with Treg people-data tools. 0.0089USD covers email finding, not verification/enrichment.85% cheaper is vendor test on292people; not an independent general benchmark. Current connector6895stars differs from article6400snapshot; keep attributed observed values.',limits:'GitHub license metadata NOASSERTION; source license requires actual text. No external project executed and no tool installed.'},
 {key:'deepseek-superagent',importance:'high',sourceDate:'2026-10-31',urls:['https://github.com/deepseek-ai/dsh-superagent-prototype','https://www.qbitai.com/2026/10/506904.html'],facts:'Official README labels research prototype for one repository bundled for DeepSeek Harness,not official product. Some architecture directions not implemented. MIT,nonfork,official owner,firstcommitOct31. Acts only when asked or allowed by team rules.',limits:'Do not generalize architectural aspiration to complete production implementation or unrestricted autonomous action.'}
];
const now=new Date().toISOString();
for(const f of findings){f.reviewedAt=now;f.evidence=f.urls.map(url=>source(url)).filter(Boolean);}
const suspicious=results.filter(r=>r.success&&r.chars<400).map(r=>({...r,factualVerification:false,reason:r.url.includes('mp.weixin')?'HTTP200 verification wall;72 chars,not article body':'Shell/summary page;publisher API full text separately retained'}));
await writeFile(base+'independent-findings.json',JSON.stringify({runDate:date,checkedAt:now,findings,suspicious,sourceCount:results.length},null,2)+'\n');
console.log(JSON.stringify({findings:findings.length,suspicious:suspicious.length,sourceCount:results.length}));
